                    1.0 :
                    multiplier_scale * (cls_cfl > 0.0 ? fmin(1.0, 0.1 * omega_max / cls_cfl) : 1.0);
    if (screen) {
      TEST_CHECK(gkyl_compare(((const double *)gkyl_array_cfetch(screen, loc))[0], mult, 2e-12));
